/**
 * Every string the boundary instrument shows, in the instrument register:
 * lowercase, middot-separated, mechanism facts only. The panel never
 * narrates its own construction (design.md §4, 2026-08-27) — each line
 * states something about where components run, not about how this demo
 * manages to show it.
 *
 * Prose strings carry typographic marks directly (voice.md §8); anything
 * quoting real code or real error text keeps straight quotes.
 */

/** The instrument's four states, in the order the deck walks them. */
export type Beat = "hydrated" | "refused" | "rest" | "split";

/** The file's first line, worn on the card the way a file wears it. */
export const DIRECTIVE_LINES: Record<Beat, string> = {
  hydrated: '"use client";',
  refused: "// no directive",
  rest: "// no directive",
  split: "// no directive",
};

/** Which side of the boundary card.tsx itself is on, for the badge. */
export const SIDES: Record<Beat, "client" | "server"> = {
  hydrated: "client",
  refused: "server",
  rest: "server",
  split: "server",
};

/** The rows under the card: capabilities, the stop, the bill, the split. */
export const FACTS: Record<Beat, readonly string[]> = {
  hydrated: [
    "bought: useState and onClick — the copy button works",
    "paid: the fetch runs in your tab now — one request per visitor, nothing shared",
    "paid: process, the secrets, the cached entry — the whole file crossed",
  ],
  refused: [
    "the build stopped here — nothing shipped",
    "onClick fails the same way: the click arrives after the server has hung up",
    "the error names its fix: one directive",
  ],
  rest: [
    "runs in Node: databases, secrets, the filesystem",
    "ships 0 kB of JavaScript",
    "renders once, returns HTML, and is gone",
  ],
  split: [
    '"use client" moved into copy-button.tsx — one directive, one small file',
    "the fetch is back in Node.js — cached once, served to everyone",
    "shipped to the browser: the button, and only the button",
  ],
};

/** The seam under the card — the one fact each state proves. */
export const SEAMS: Record<Beat, string> = {
  hydrated:
    "the directive claims the whole file, and every file it imports · the line is drawn at build time, not per render",
  refused:
    "useState keeps a value between renders · a render that happens once has no between",
  rest: "no directive · a Server Component, like every file that doesn’t say otherwise",
  split:
    "a Server Component can import a Client Component · the directive sits on the smallest file that needs it",
};

/**
 * The refusal, verbatim. This is the exact string Turbopack prints when a
 * file without the directive asks for useState — read out of the next-swc
 * binary, 2026-08-27, so the truth pass can check the panel against the
 * real error. Straight quotes throughout: it quotes the compiler.
 */
export const REFUSAL_ERROR =
  "You're importing a component that needs `useState`. This React Hook only works in a Client Component. To fix, mark the file (or its parent) with the `\"use client\"` directive.";

/** The overlay's file line — the card's own name, where dev points. */
export const REFUSAL_FILE = "./card.tsx";

/** Deck step one: the change the hash itself asks for. */
export const STEP_ONE_LABEL = "Add a copy button";
export const STEP_ONE_DETAIL = "useState + onClick";

/** Deck step two: the fix the error just named. Real code, straight quotes. */
export const STEP_TWO_LABEL = '"use client"';

/** Deck step three: the fix no error message suggests. */
export const STEP_THREE_LABEL = "Extract the button";
export const STEP_THREE_DETAIL = "copy-button.tsx";

/** Chrome, top-right: instrument housekeeping, disabled at rest. */
export const RESET_LABEL = "reset";

import { describe, expect, test } from "bun:test";
import {
  DIRECTIVE_LINES,
  FACTS,
  REFUSAL_ERROR,
  SEAMS,
  SIDES,
  STEP_THREE_DETAIL,
  STEP_TWO_LABEL,
} from "./copy";

const BEATS = ["rest", "refused", "hydrated", "split"] as const;

describe("the refusal", () => {
  test("quotes the compiler verbatim (next-swc binary, 2026-08-27)", () => {
    expect(REFUSAL_ERROR).toBe(
      'You\'re importing a component that needs `useState`. This React Hook only works in a Client Component. To fix, mark the file (or its parent) with the `"use client"` directive.'
    );
  });

  test("keeps straight quotes — it is quoted code, not prose (voice.md §8)", () => {
    expect(REFUSAL_ERROR).not.toContain("’");
    expect(REFUSAL_ERROR).not.toContain("“");
  });
});

describe("the beats", () => {
  test("the directive appears exactly once, on the hydrated card, in real syntax", () => {
    expect(DIRECTIVE_LINES.hydrated).toBe('"use client";');
    expect(DIRECTIVE_LINES.rest).toBe("// no directive");
    expect(DIRECTIVE_LINES.refused).toBe("// no directive");
    expect(DIRECTIVE_LINES.split).toBe("// no directive");
  });

  test("card.tsx crosses the boundary once and comes back with the split", () => {
    expect(SIDES.rest).toBe("server");
    expect(SIDES.refused).toBe("server");
    expect(SIDES.hydrated).toBe("client");
    expect(SIDES.split).toBe("server");
  });

  test("the split names the file that carries the directive", () => {
    expect(FACTS.split[0]).toContain(STEP_THREE_DETAIL);
    expect(SEAMS.split).toContain("Client Component");
  });

  test("every beat carries three fact rows and a seam", () => {
    for (const beat of BEATS) {
      expect(FACTS[beat]).toHaveLength(3);
      expect(SEAMS[beat].length).toBeGreaterThan(0);
    }
  });
});

describe("register (voice.md §8)", () => {
  test("prose apostrophes are typographic", () => {
    for (const beat of BEATS) {
      for (const line of [...FACTS[beat], SEAMS[beat]]) {
        expect(line).not.toContain("'");
      }
    }
  });

  test("the deck's directive label is real code with straight quotes", () => {
    expect(STEP_TWO_LABEL).toBe('"use client"');
  });
});

"use client";

import { cn } from "@repo/design-system/lib/utils";
import { useCallback, useState } from "react";

/**
 * The one component in this chapter that genuinely needs the browser:
 * clipboard access and a "copied" tick have no server-side counterpart.
 * In the split beat this file is the entire client bundle of the card —
 * the directive above is the boundary, drawn at its smallest.
 */
export function CopyButton({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(() => {
    navigator.clipboard
      .writeText(value)
      .then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      })
      .catch(() => {
        // Clipboard access denied: the button simply doesn't tick.
      });
  }, [value]);

  return (
    <button
      className={cn(
        "inline-flex items-center rounded-md border border-foreground/15 px-2 py-0.5 font-mono text-muted-foreground text-xs transition-colors",
        "hover:border-foreground/30 hover:text-foreground",
        copied && "border-ht-cyan-700/40 text-ht-cyan-800 dark:text-ht-cyan-300"
      )}
      onClick={handleCopy}
      type="button"
    >
      {copied ? "copied" : "copy"}
    </button>
  );
}

import { cacheLife } from "next/cache";
import { formatClock, formatStamp } from "../format";
import { InlineCode } from "../inline-code";

interface LatestCommit {
  sha: string;
  stamp: string;
  subject: string;
}

interface ServerFacts {
  commit: LatestCommit | null;
  nodeVersion: string;
  renderedAt: string;
}

/**
 * The work developers expect from a Server Component: fetch something and
 * render it. The something is this repo's own latest commit — data the
 * making-of aside already trades in. Drift is accepted and disclosed on
 * the card: `hours` revalidates the entry hourly, and a commit that lands
 * inside the window ships with the deploy it triggers anyway, so the
 * stale reading rarely outlives the push that obsoleted it (2026-08-27).
 * One refetch an hour also keeps GitHub's unauthenticated rate limit
 * (60/hour per IP) out of the picture entirely.
 */
async function getServerFacts(): Promise<ServerFacts> {
  "use cache";
  cacheLife("hours");

  let commit: LatestCommit | null = null;
  try {
    const response = await fetch(
      "https://api.github.com/repos/hasToggle/hasToggle.dev/commits/main",
      // GitHub rejects requests without a User-Agent.
      { headers: { "user-agent": "hasToggle.dev" } }
    );
    if (response.ok) {
      const data = (await response.json()) as {
        commit: { committer: { date: string }; message: string };
        sha: string;
      };
      commit = {
        sha: data.sha.slice(0, 7),
        stamp: formatStamp(new Date(data.commit.committer.date)),
        subject: data.commit.message.split("\n")[0],
      };
    }
  } catch {
    // GitHub unreachable when the entry renders: fall back to residence
    // facts alone rather than caching an invented reading.
  }

  return {
    commit,
    nodeVersion: process.version,
    renderedAt: new Date().toISOString(),
  };
}

interface ServerCardProps {
  /**
   * The split beat's client island, threaded in from the demo so this
   * Server Component can import nothing marked "use client" itself. When
   * present it renders inside a drawn boundary: the dashed ring is the
   * import graph's line, at its smallest.
   */
  button?: React.ReactNode;
}

/**
 * The rest and split beats' body: a Server Component, rendered in Node
 * and passed through the client panel as a finished slot — props crossing
 * the boundary as serialized data, which is the chapter's own mechanism.
 * `process.version` is proof of residence: browsers don't have one.
 */
export async function ServerCard({ button }: ServerCardProps) {
  const facts = await getServerFacts();

  return (
    <div className="flex flex-col gap-2">
      {facts.commit ? (
        <>
          <p className="flex flex-wrap items-center gap-x-3 gap-y-1 font-display font-medium text-2xl text-foreground tracking-tight">
            <span>
              latest commit{" "}
              <span className="font-mono text-ht-cyan-700 text-xl dark:text-ht-cyan-300">
                {facts.commit.sha}
              </span>
            </span>
            {button ? (
              <span className="inline-flex items-center gap-2 rounded-md border border-ht-orange-700/40 border-dashed px-1.5 py-1 dark:border-ht-orange-500/40">
                {button}
                <span className="font-mono text-[0.65rem] text-ht-orange-800 dark:text-ht-orange-300">
                  copy-button.tsx
                </span>
              </span>
            ) : null}
          </p>
          {/* The subject may be a full merge line; it truncates so the
              stamp — the checkable half — never does. */}
          <p className="flex items-baseline gap-2 font-mono text-muted-foreground text-xs">
            <span className="min-w-0 truncate">{facts.commit.subject}</span>
            <span aria-hidden="true" className="shrink-0 opacity-55">
              ·
            </span>
            <span className="shrink-0">{facts.commit.stamp}</span>
          </p>
        </>
      ) : (
        <p className="font-display font-medium text-2xl text-foreground tracking-tight">
          Rendered in Node.js{" "}
          <span className="text-ht-cyan-700 dark:text-ht-cyan-300">
            {facts.nodeVersion}
          </span>
        </p>
      )}
      <p className="text-foreground/75 text-sm/6">
        {facts.commit ? (
          <>
            Fetched from <InlineCode>api.github.com</InlineCode>&#32;in{" "}
            <InlineCode>node {facts.nodeVersion}</InlineCode>&#32;at&#32;
            {formatClock(new Date(facts.renderedAt))}, then cached — re-served
            to every visitor until the entry revalidates or a deploy replaces
            it.
          </>
        ) : (
          <>
            at {formatClock(new Date(facts.renderedAt))}, then cached —
            re-served to every visitor until the entry revalidates or a deploy
            replaces it.
          </>
        )}
      </p>
    </div>
  );
}

